  insert into _d values
    ($q$Пирвели$q$, $q$Гиорги Гхвиношвили$q$, $q$гиорги гхви%$q$, 'RNJ757', 'GZ9YG2', 1,
     $q$Посылка из старых сельскохозяйственных долин планеты Сол пришла в рассохшемся деревянном ящичке, бережно перевязанном грубой пеньковой бечевкой. Внутри лежали высушенные черенки автохтонной лозы сорта Саперави, сохраненного еще со времен первых поселений на Соле, горсть прошлогодних орехов и пожелтевшая открытка с видом на холмы. Открытка от младшей сестры Нино, в ней написано: «Гиорги, родной мой! В наших краях совсем не осталось чистого воздуха — правительство строит третий пояс химических обогатителей, едким смогом затянуло даже горные перевалы, молодежь сотнями вербуется на орбитальные верфи, а старые дедовские виноградники вырубают под склады. Мы каждый вечер зажигаем лампаду за тебя и молимся, чтобы ты где-то там, под настоящим небом, вырастил живую лозу. Не возвращайся на Сол, Гиорги, здесь больше нет жизни для свободных людей. Строй свой дом на Парадайзе или еще где и держись за эту землю до конца».$q$,
     $q$Вторым вложением был запечатанный металлом цилиндрический контейнер с гербовой сургучной печатью Фонда Уильяма Тёрнера, содержащий эталонные винные дрожжи. В официальном предписании попечительского совета фонда значится: «Капитану колонизационной экспедиции Гхвиношвили Г. Уведомляем, что финансовое обеспечение миссии „Пирвели“ продлено по закрытой статье непрерывности Уильяма Тёрнера. В случае обнаружения любых признаков биологических аномалий или попыток силового вмешательства предписывается сохранять статус-кво автономной общины и ни при каких условиях не передавать права на землю любым представителям Сола. К предписанию приложена личная выписка из распоряжения основателя Уильяма Тёрнера перед его исчезновением: „Пусть старик Гиорги посадит виноградники и построит дом. Это вино еще понадобится тем, кто придет следом расплачиваться за наши грехи“».$q$),
    ($q$Пирвели$q$, $q$Арсен Серосян$q$, $q$арсен серо%$q$, 'HFUY4X', 'S6UN69', 1,
     $q$Картонная коробка со штемпелем перевалочного орбитального хаба «Сол-7-0-1» пахла машинным маслом, пережженной проводкой и дешевой соей — родным станционным воздухом Арсена. Внутри лежал вакуумный пакет сушеной рыбы, к сожалению давно протухшей, и помятая схема вентиляции. Записка от двоюродного брата Вано, накарябанная прямо поверх чертежа, гласила: «Арсенчик, здорово! Шлю тебе банку нашей фирменной воблы из третьего гидропонного отсека, а то небось забыл вкус настоящей станционной жратвы. В наших доках опять забастовка, третью неделю сидим на половине пайки, фильтры в нижних жилых ярусах свистят и травят гарью. Мужики на причале до сих пор ржут и не верят, что ты реально ходишь по настоящей траве и над твоей головой нет стальной переборки! Говорят, ты там у капитана правая рука? Держись за эту планету зубами, брат. На наши ржавые консервные банки всегда успеешь вернуться».$q$,
     $q$Под слоем упаковочного пластика лежал номер трехлетней давности столичного журнала «Звездный Первопроходец» с сияющей на обложке актрисой Магдой Берт. На полях журнального разворота брат оставил тревожную приписку маркером: «Гляди, первопроходец, твоя зазноба теперь гремит по всей Метрополии! Слыхал, ее тоже унесло куда-то в твою сторону на челноке для богачей. Но главное не это, Арсен. Месяц назад ко мне в бар заглядывал безопасник в штатском — выспрашивал про погибшего старпома „Пирвели“, на чье место тебя впихнули перед стартом. Говорят, того бедолагу столкнули в шахту вовсе не из-за пьяной драки, а люди из контрразведки, потому что он нашел в навигационных логах Тёрнера закрытые координаты. Не лезь в дела начальства, Арсен, крути гайки и помалкивай».$q$),
    ($q$Пирвели$q$, $q$Степан Рязин$q$, $q$степан рязи%$q$, 'J2U57N', 'JPU2EZ', 1,
     $q$Тяжелая фанерная бандероль с заводских окраин промышленного сектора Гелиос-Пром на планете Сол была опечатана свинцовой пломбой механического цеха. Внутри лежало письмо от сестры Ольги, написанное торопливым мелким почерком, гласило: «Здравствуй, Степа. На рудниках у нас совсем беда: завод перевели на казарменное положение, смены по четырнадцать часов, за малейший брак грозят каторгой и трибуналом. Мама совсем сдала, глазами почти не видит, но каждый день сидит у окна и гладит твой старый сварочный щиток. Она плачет и просит передать тебе: „Сынок, береги руки, не перечь офицерам и не суйся в чужие тайны“. Нам не нужны посмертные ордена, Степочка, нам нужно, чтобы ты вернулся домой живым».$q$,
     $q$В фабричном опломбированном ящике с запасными термопарами и фильтрами высокого давления лежал завернутый в ветошь старый каленый накидной ключ с выбитым клеймом первой бригады Степана. В полой рукояти ключа пряталась крошечная перфолента от активистов заводского стачечного комитета с текстом: «Степан, до цехов дошли секретные сводки: флот Сола отправил ударный корабль к системе Сигма Драконис под видом спасательной миссии. Военные ищут там залежи сплава, идентичного тем образцам, что ты тайно вывез с Гелиоса и Бетельгейзе. Если ты наткнешься на чужой металл или конструкции — спрячь так, чтобы ни одна армейская ищейка не нашла. Власти хотят создать на этой основе оружие планетарного подавления, чтобы окончательно закрутить колониям ошейник. Не отдавай им чужие технологии, Степан, чего бы тебе это ни стоило».$q$),
    ($q$Пирвели$q$, $q$Сильвио Чирзанне$q$, $q$сильвио чирз%$q$, 'DD7HBG', '4ZTN6H', 1,
     $q$Академическая бандероль из Института Высшей Топологии Сол-2 содержала увесистый фолиант свежей монографии по квантовой кристаллографии. На титульном листе рукой старого учителя, профессора Вальтера, было выведено: «Моему гениальному и невыносимому ученику Сильвио Чирзанне. Коллеги на кафедре до сих пор крутят пальцем у виска, вспоминая твои гипотезы о нелинейных живых кристаллах, но эта монография доказывает твою теоретическую правоту. Не зарывай свой мозг в примитивную колониальную рутину, Сильвио. Помни: где-то во Вселенной бьется сердце гигантского спящего математического механизма, и ты единственный, кто способен рассчитать точку его пробуждения».$q$,
     $q$Вторым документом был запечатанный тяжелым сургучом официальный пакет Специального Комитета Научных Исследований Сола с грифом «Особой важности / Лично в руки». В секретном циркуляре ведомства значилось: «Действительному члену экспедиции Чирзанне С. Настоящим уведомляем, что переданные вами ранее матрицы гравиметрических аномалий четвертой планеты Сигмы Драконис показали критическое совпадение со скрытыми сейсмическими профилями луны Бетельгейзе 2-1. Вам строжайше предписывается прекратить любые самостоятельные попытки дешифровки резонансных импульсов. Все полученные материалы, топологические расчеты и образцы кристаллов немедленно передать под опись уполномоченному СБ Сола Еве Формман. Нарушение режима секретности карается обвинением в измене родине и бессрочной изоляцией».$q$),
    ($q$Парадайз$q$, $q$Эндрю Воллас$q$, $q$эндрю волл%$q$, 'DWAJNF', 'EUFQYN', 1,
     $q$В конфиденциальной докладной записке главного поверенного холдинга «Воллас Иншуренс Групп» значилось: «Господин Воллас! Положение катастрофическое. Ваше молчание длится уже два с половиной года. Члены совета директоров вступили в тайный сговор с финансовыми синдикатами Сола и подали иск в Верховный арбитраж о признании вас безвестно отсутствующим. Если вы не подтвердите дееспособность личной биометрической подписью в течение шести месяцев, все трастовые счета будут заморожены, а контрольные пакеты акций уйдут с молотка за бесценок. Умоляю: подайте сигнал, что вы живы, пока нас не разорили окончательно!»$q$,
     $q$Вторым конвертом из плотной тисненой бумаги с ароматом дорогого столичного парфюма оказалось личное письмо от бывшей светской фаворитки Эндрю с планеты Сол. В письме светской львицы Вивьен было начертано: «Дорогой Эндрю, надеюсь, твой дикий отдых на фронтире стоит тех триллионов, которые прямо сейчас утекают у тебя сквозь пальцы. Прилагаю счет за стоянку твоей орбитальной суперъяхты — оплати его, если не хочешь, чтобы судебные приставы пустили судно с аукциона. И самое скверное: на прошлой неделе ко мне в апартаменты являлись следователи государственной безопасности. Они изъяли весь архив по рудникам Бетельгейзе 2-1 и задавали крайне опасные вопросы о твоих секретных договорах страхования „нештатных геологических полостей“. Они знают, Эндрю. Беги дальше, если можешь, или возвращайся с армией лучших адвокатов».$q$),
    ($q$Парадайз$q$, $q$Антуан Зиппер$q$, $q$антуан зипп%$q$, '5FH23N', 'JYXV79', 1,
     $q$Контейнер от старшего брата Жюльена, управляющего семейным холдингом «Зиппер Тек», содержал письмо от старшего брата Жюльена на бланке концерна, в котором говорилось: «Антуан, твое детское упрямство начинает стоить нам слишком дорого. Мы получили от Военного министерства Сола грант на восемьсот миллиардов кредитов под развертывание сети мгновенной связи по жесткому армейскому протоколу. Генералам нужны не твои сопливые бредни о свободе информации для колоний, а закрытые военные ретрансляторы. Немедленно заверши калибровку фазовых контуров и пришли спецификации. Хватит валять дурака на дикой планете — без моих связей ты до сих пор сидел бы в подвале нищим задротом».$q$,
     $q$Под нижним слоем упаковочного полимера Антуан обнаружил крошечный свинцовый футляр с цифровым чипом, на котором был записан трехсекундный фрагмент ночной синтезаторной музыки из его закрытой лаборатории. В зашифрованном коде файла мерцала строчка от Линь Цзинь: «Антуан, если ты слышишь это — мои друзья смогли перехватить грузовой контейнер твоего брата перед отправкой. Я знаю, что ты никогда не простишь меня за взлом серверов Волласа с твоего терминала. Но поверь мне: правительство Сола строит цифровой ошейник для колоний на костях твоих открытий. Военные скрыли правду о том, что образец BTG-SI-4, на котором держится твоя связь — это фрагмент живого разума, уничтоженного спецслужбами. Не помогай Жюльену отдать сеть в руки палачей или Волласу чтобы еще сильнее укрепить власть капитала. Я жива, и я верю, что ты все еще тот человек, которого я полюбила».$q$),
    ($q$Парадайз$q$, $q$Магда Берт$q$, $q$магда берт%$q$, 'JPSTNT', 'HFSEJH', 1,
     $q$Персональный пакет от генерального продюсера студии «Сол-Медиа Пикчерз» содержал документ, подтверждающий получение высшей награды Киноакадемии. В письме от продюсера студии значилось: «Божественная Магда! Ты превзошла саму себя! Наш фильм-приквел об отважной колонистке, покоряющей опасные рубежи, собрал рекордную кассу на всех мирах Метрополии! Газеты захлебываются от восторга, толпы фанатов штурмуют офис студии, а жюри единогласно присудило тебе высшую награду за мужество в искусстве! Мы ждем твоего триумфального возвращения на первом же борту спасателей. Как прилетишь - надень свое лучшее платье и сойди по трапу богиней. Твой сорокамиллионный гонорар уже зачислен на счета!»$q$,
     $q$Вторым свертком был скромный холщовый мешочек, а в заляпанном от материнских слез письме пожилой матери говорилось: «Магдочка, доченька моя ненаглядная! Я не верю ни единому слову из этих лживых праздничных передач по головизору. Твой продюсер врет журналистам, что ты отдыхаешь на сказочном курорте — мое сердце разрывается от боли, я чую, что ты попала в беду и задыхаешься от ужаса среди чужих холодных звезд. Умоляю тебя, брось эти проклятые съемки, брось эту фальшивую мишуру и возвращайся домой. Твоя комната ждет тебя, и для меня ты навсегда останешься маленькой девочкой, а не недосягаемой звездой экрана».$q$),
    ($q$Парадайз$q$, $q$Алиссия Тёрнер$q$, $q$алиссия тёрн%$q$, 'UPQ55P', 'RBCCM2', 1,
     $q$Изящный кейс из белой кожи содержал официальный пакет доверительного управления «Тёрнер Лимитед». В нотариальном извещении доверительных управляющих сообщалось: «Госпоже Алиссии Тёрнер. Уведомляем вас, что несмотря на ожесточенные судебные иски совета директоров, пытающегося заморозить часть наследства, автоматические выплаты из закрытого слепого траста вашего отца Уильяма Тёрнера продолжают перечисляться строго по графику. Средства направляются на финансирование первой экспедиции „Пирвели“ и инфраструктурные маяки сектора Сигма Драконис. Основатель фонда заблокировал возможность отмены этих траншей даже при подтверждении факта его физической смерти.».$q$,
     $q$На самом дне, под тайной перегородкой, лежала старая аналоговая фотокарточка: десятилетняя счастливая Алиссия сидит на плечах отца на фоне стартовой вышки космодрома. На обороте снимка рукой старого личного помощника Тёрнера было написано: «Алиссия, протоколы трибунала с подписью капитана Бэтча о гибели твоего отца от рук пиратов — это бессовестная правительственная фальшивка. Двенадцать лет назад Уильям лично заглушил маяки кодами высшего допуска и увел судно в систему Сигма Драконис. Он похитил из правительственного спецхранилища какую-то внеземную технологию и улетел на Парадайз, зная, что именно здесь находится колыбель чужого разума. Он оплатил модуль Гхвиношвили ради тебя и ради того, чтобы у людей был шанс. Ищи его след на планете — отец ждал тебя здесь до конца. Код его аварийного маяка 142473. Запусти ИИ агента модуля на поиск, и ты найдешь отца».$q$),
    ($q$Фридом$q$, $q$Дилан Бэтч$q$, $q$дилан бэтч%$q$, 'QBFY5D', 'PV4Z34', 1,
     $q$Посылка пришла от взрослого сына, офицера-выпускника столичной Военно-космической Академии Сола. В письме сына, лейтенанта Роберта Бэтча, говорилось: «Здравствуй, отец! Я закончил Академию первым на выпуске и получил назначение вахтенным офицером на головной патрульный крейсер Метрополии. Отец, на занятиях по тактике преподаватели до сих пор разбирают твои боевые операции. Я безмерно горжусь тем, что ношу твою фамилию, и сделаю всё, чтобы быть достойным офицерской чести рода Бэтчей. Береги себя на Парадайзе и возвращайся с победой. Мы молимся за тебя каждый день».$q$,
     $q$Вторым вложением был гербовый конверт с тяжелой сургучной печатью Командующего колониальными силами Сола. В секретной директиве Главного штаба Армии Сола за подписью маршала Вогана значилось: «Полковнику Бэтчу Д. Настоящим уведомляем о присвоении вам звания коменданта сектора. Приказываем: в случае обнаружения на Сигме Драконис IV аномальных технологий все непосредственные полномочия по руководству миссией передать куратору СБ Сола Формман. Силами гарнизона „Фридома“ обеспечить глухую изоляцию гражданских модулей. В протоколы контрразведки не вмешиваться. Помните присягу, полковник: безопасность государства превыше любых частных моральных терзаний».$q$),
    ($q$Фридом$q$, $q$Ева Формман$q$, $q$ева форм%$q$, '289W2W', 'XM7RMK', 5,
     $q$Личная посылка из центрального столичного округа Сол-2 была доставлена в безымянной коробке от младшей сестры Евы, внутри которой лежала открытка. В открытке с видом набережных столицы на планете Сол-2 мелким почерком сестры Клары было написано: «Ева, милая, с днем рождения (хотя я и не знаю когда доставят письмо)! Опять ты встречаешь его в ледяном космосе, на очередной безымянной спецоперации, о которой нам даже нельзя знать. У нас родился маленький Лео — он улыбается точь-в-точь как наш папа... Ева, бросай эту страшную службу в контрразведке. Твоя квартира в центре пустует, я прихожу туда поливать цветы, и мне становится жутко от этой мертвой тишины. Умоляю, возвращайся живой. Нам нужна ты, а не твои секретные государственные заслуги».$q$,
     $q$Вторым предметом оказался опломбированный черный криптографический куб наивысшей категории допуска «Ноль-Омега» от Директората Специальных Операций СБ Сола. В расшифрованном приказе высшего руководства СБ Сола значилось: «Спецагенту Формман Е. Объект на Сигме Драконис IV идентифицирован как материнское ядро кремниевой цивилизации Силикоидов, родственное уничтоженному вами очагу на Бетельгейзе 2-1. Задача высшей государственной важности: обеспечить монопольный захват сервисного манипулятора Тёрнера и центрального узла структуры для аналитических центров Сола. Гражданские лица из модулей „Пирвели“ и „Парадайз“ признаются носителями критической утечки. В случае невозможности скрытной эвакуации артефакта активировать протокол санитарной зачистки полигона. Ни один свидетель, включая армейский состав и полковника Бэтча, не должен покинуть планету живым».$q$),
    ($q$Фридом$q$, $q$Нателла Исайро$q$, $q$нателла исай%$q$, '2BA5YC', 'WXZ7SS', 1,
     $q$Письмо пришло от старого сокурсника по военно-медицинской академии, ныне главного хирурга тылового эвакуационного госпиталя на Тезее-4. В письме фронтового врача майора Коваля говорилось: «Натка, привет! Надеюсь у тебя все хорошо, потому что у нас тут ад: тыловые интенданты урезали нормы обезболивающих втрое, а эшелоны с искалеченными работягами из шахтерских колоний идут сплошным потоком. Ребята горят от болевого шока, а генералы отчитываются о великих победах. Нателла, держись. Ты лучший полевой хирург, которого я знал. Не давай тамошним солдафонам сломать твой фирменный врачебный триаж».$q$,
     $q$Второй пакет был передан по негласным связям подпольного профсоюза ветеранов колониальной милиции — внутри лежала копия закрытого определения военного суда по делу Маркуса Кейна с приколотой рукописной запиской. В записке без подписи от офицеров милиции было начертано: «Доктор Исайро! Трибунал засудил Маркуса Кейна на 35 лет каторги исключительно для того, чтобы скрыть правду: шахту на Бетельгейзе подорвали, чтобы не допустить взрыва всей луны, а добывали там компоненты оружия массового поражения. Контрразведка СБ под началом Евы Формман сейчас зачищает всех медиков, знавших о препарате BTG-SI-4. Мы знаем, что вы спасли полковника Бэтча экспериментальной биополимерной эмульсией на основе этого минерала. Ни в коем случае не показывайте Формман снимки позвоночника Бэтча — если она поймет, что кремниевый каркас прижился в человеке, вас обоих пустят под нож в закрытых лабораториях».$q$),
    ($q$Фридом$q$, $q$Ганеш Шарма$q$, $q$ганеш шарм%$q$, '7DRWS3', 'NMCG9B', 1,
     $q$Полотно из грубой ткани пахло кардамоном, сандалом и сухим ветром священного города Варанаси на планете Сол-1 — посылка от младшего брата и многочисленных племянников Ганеша. Внутри лежали пустые мешочки из под пряностей и длинный семейный свиток. В письме от младшего брата Раджеша говорилось: «Дорогой брат Ганеш! Шлем тебе специи нашего помола. У нас все благополучно: прошли дожди, рисовые чеки полны воды, а старшая племянница выходит замуж. Мы молимся за твой покой и чистоту сердца среди чужих холодных звезд. Помни, Ганеш: всё сущее связано в великий круговорот сансары. Какое бы зло ни совершили люди вокруг тебя, закон кармы нерушим, и каждый ответит за содеянное. Береги свою душу от ярости и возвращайся к нам невредимым».$q$,
     $q$Второй частью посылки стала тяжелая академическая бандероль от деканата биофизики Университета Татимем Санавидван, где лежал сигнальный экземпляр фундаментального атласа экзобиологии с главой о работах доктора Шармы. В тайном письме от бывшего аспиранта Амита, спрятанном между страниц монографии, было напечатано: «Учитель! Мы втайне от ректората прогнали ваши заблокированные спектрограммы с Бетельгейзе 2-1 через новые квантовые алгоритмы кафедры. Мы математически доказали: оптические импульсы кремниевых кристаллов — это синтаксис живого, мыслящего языка! Мы не знаем, что заставило вас молчать но мы знаем, что у вас был контакт. Если вы найдете следы этого разума на Парадайзе — умоляем, не молчите снова. Защитите их жизнь. Наука помнит ваше имя, и истина стоит того, чтобы за нее бороться».$q$);

  select id into lin from characters where lower(btrim(name)) like 'линь цзин%' limit 1;
  if lin is null then missing := missing || ' Линь Цзинь;'; end if;
  for r in select * from _d loop
    if not exists (select 1 from characters where lower(btrim(name)) like r.pat) then missing := missing || ' ' || r.name || ';'; end if;
  end loop;
  if missing <> '' then raise exception 'Не найдены персонажи:% — проверьте имена в разделе «Персонажи»', missing; end if;

  -- коды не должны принадлежать чужим объектам
  for r in select * from _d loop
    if exists (select 1 from content_items where upper(trigger_code) in (r.codeA, r.codeB) and coalesce(summary, '') not like 'Доставка с Сола%') then
      raise exception 'Код % или % уже занят другим объектом', r.codeA, r.codeB;
    end if;
  end loop;

  for r in select * from _d loop
    select id into hero from characters where lower(btrim(name)) like r.pat order by name limit 1;
    blkB := jsonb_build_array(
      jsonb_build_object('type', 'text', 'md', '## Второе вложение · ' || r.name, 'width', 'full', 'style', 'plain'),
      jsonb_build_object('type', 'text', 'md', r.p2, 'width', 'full', 'style', 'plain'));

    -- 2) вложение
    select id into idB from content_items where trigger_code = r.codeB;
    if idB is null then
      insert into content_items (trigger_code, type, body, playback, unlock_condition, blocks)
      values (r.codeB, 'text', r.p2, 'unlimited', '{"type":"player_choice"}', blkB) returning id into idB;
    end if;
    update content_items set
      type = 'text', body = r.p2, blocks = blkB, playback = 'unlimited',
      unlock_condition = '{"type":"player_choice"}'::jsonb, choice_options = null, module_scope = null,
      summary = 'Доставка с Сола — ' || r.name || ': вложение 2 (получатель / Линь за ' || r.price || ' крист.)',
      character_scope = array[hero, lin], price = 0,
      variants = jsonb_build_array(jsonb_build_object(
        'id', 'lin' || lower(r.codeB), 'price', r.price, 'character_ids', jsonb_build_array(lin), 'module_ids', '[]'::jsonb,
        'blocks', blkB, 'body', r.p2, 'choice_options', '[]'::jsonb)),
      viewed = coalesce(viewed, false)
    where id = idB;

    -- 1) посылка
    blkA := jsonb_build_array(
      jsonb_build_object('type', 'text', 'md', '## Доставка с Сола · ' || r.name || E'\n*Модуль «' || r.module || '»*', 'width', 'full', 'style', 'plain'),
      jsonb_build_object('type', 'text', 'md', r.p1, 'width', 'full', 'style', 'plain'));
    select id into idA from content_items where trigger_code = r.codeA;
    if idA is null then
      insert into content_items (trigger_code, type, body, playback, unlock_condition, blocks)
      values (r.codeA, 'text', r.p1, 'unlimited', '{"type":"always"}', blkA) returning id into idA;
    end if;
    update content_items set
      type = 'text', body = r.p1, blocks = blkA, playback = 'unlimited',
      unlock_condition = '{"type":"always"}'::jsonb, module_scope = null, character_scope = null, price = 0, variants = '[]'::jsonb,
      choice_options = jsonb_build_array(jsonb_build_object('id', 'open2', 'label', 'Вскрыть второе вложение', 'nextContentId', idB)),
      summary = 'Доставка с Сола — ' || r.name || ': посылка',
      viewed = coalesce(viewed, false)
    where id = idA;
  end loop;
end $$;

select summary, trigger_code, price,
       coalesce((select string_agg(c.name, ', ') from characters c where c.id = any(ci.character_scope)), 'все') as "кому",
       (select string_agg((v->>'price') || ' крист.', ', ') from jsonb_array_elements(ci.variants) v) as "Линь платит"
from content_items ci where summary like 'Доставка с Сола%' order by summary;
